import React, { useEffect, useState } from 'react';
import { useSearchParams, Link } from 'react-router-dom';
import {Container,Typography,Grid,Paper,Box,Chip,Divider,Card,CardContent,CardMedia} from '@mui/material';

import { ChevronLeft, Triangle, ArrowUp, ArrowDown } from 'lucide-react';
import {AreaChart,Area,XAxis,YAxis,CartesianGrid,ResponsiveContainer, Tooltip} from 'recharts';

// --- モックデータ ---
const data = [
  { name: '第1号', blue: 1.2, orange: 2.0 },
  { name: '第2号', blue: 1.5, orange: 1.8 },
  { name: '第2号', blue: 1.1, orange: 2.3 },
  { name: '第3号', blue: 1.5, orange: 2.0 },
  { name: '第3号', blue: 1.1, orange: 1.8 },
  { name: '第4号', blue: 2.0, orange: 2.6 },
  { name: '第5号', blue: 1.5, orange: 2.1 },
  { name: '第5号', blue: 2.2, orange: 2.8 },
];

type RankingRow = {
  issue_label: string;
  title: string;
  rank_num: number;
};

interface Work {
  id: number;
  work_id: number;
  title: string;
  title_kana: string;
  title_eng: string;
  author: string;
  serialization_start_date: string;
  end_flg: boolean;
  story: string;
  genre: string;
  created_at: string;
  updated_at: string;
  peak_rank: number;
  status: string;
  image_url: string;
  official_url: string;
};

interface Volume {
  volume: number;
  releaseDate: string;
  coverimage: string;
  price: number;
  isbn: string;
  description: string;
  pages: number;
}

interface RankingData {
  title: string;
  [key: string]: string | number;
}

type SeriesRanking = {
  series: string;
  average: number;
};

const DetailPage = () => {
  const [searchParams] = useSearchParams();
  const [mangaDetail, setMangaDetail] = useState<Work | null>(null);
  const [volumes, setVolumes] = useState<Volume[]>([]);
  const [rankingData, setRankingData] = useState<RankingData[]>([]);
  const [displayCount, setDisplayCount] = useState<number>(5); // 表示する作品数
  const [topSeries, setTopSeries] = useState<string[]>([]);
  const [averageRankings, setAverageRankings] = useState<SeriesRanking[]>([]);
  const [eachWork, setEachWork] = useState<RankingRow[]>([]);
  const [loading, setLoading] = useState(true);
  const title = searchParams.get('title');
  // 各作品の表示状態を管理
  const [visibleSeries, setVisibleSeries] = useState<{ [key: string]: boolean }>({});


  useEffect(() => {
    const fetchData = async () => {
      try {
        // 漫画詳細の取得
        if (!title) return;
        const detailResponse = await fetch(`http://localhost:8080/work/${encodeURIComponent(title)}`);
        const detailData = await detailResponse.json();
        //let manga = detailData.manga.find((m: MangaDetail) => m.title === title);

        if (!mangaDetail?.title) {
            // タイトルが存在することを確認
            if (!title) {
              console.error('Title is empty or null');
              return;
            }
        }

        setMangaDetail(detailData || null);

        // ランキングデータの取得
        fetch("http://localhost:8080/ranking")
        .then((response) => response.json())
        .then((rows: RankingRow[]) => {
          // =========================================
          // ① issueごとにまとめて「横持ち」形式へ変換
          // =========================================
          const grouped: { [issue: string]: any } = {};

          rows.forEach((row) => {
          if (!grouped[row.issue_label]) {
            grouped[row.issue_label] = {
              title: row.issue_label,
            };
          }

          grouped[row.issue_label][row.title] = row.rank_num;
          });

          const parsedData = Object.values(grouped);
          //setData(parsedData);
          setRankingData(parsedData);


          // =========================================
        // ② 作品カラム取得
        // =========================================
        const seriesColumns = Array.from(
          new Set(rows.map((r) => r.title))
        );

        // =========================================
        // ③ 平均順位計算（今までと同じロジック）
        // =========================================
        const seriesRankings: {
          [key: string]: { sum: number; count: number };
        } = {};

          // 各作品の順位の合計とデータ数を集計
        parsedData.forEach((row: any) => {
          seriesColumns.forEach((series) => {
            if (!seriesRankings[series]) {
              seriesRankings[series] = { sum: 0, count: 0 };
            }

            const rank = row[series];
            if (typeof rank === "number") {
              seriesRankings[series].sum += rank;
              seriesRankings[series].count += 1;
            }
          });
        });

        // 平均順位を計算してソート
        const rankings = Object.entries(seriesRankings)
          .map(([series, stats]) => ({
            series,
            average: stats.sum / stats.count,
          }))
          .sort((a, b) => a.average - b.average);// 平均順位が低い（上位の）順にソート

        setAverageRankings(rankings);


        // 上位作品の選出
        const topSeriesNames = rankings
        .slice(0, displayCount)
        .map((item) => item.series);

        setTopSeries(topSeriesNames);

        const initialVisibility = seriesColumns.reduce(
          (acc, series) => ({
            ...acc,
            [series]: topSeriesNames.includes(series),
          }),
          {}
        );

        setVisibleSeries(initialVisibility);



        })

      } catch (error) {
        console.error('Error fetching data:', error);
      } finally {
        setLoading(false);
      }

    }; // fetchData

    fetchData();
  }, [title]);

console.log(averageRankings);

   // 個作品の連載順位の推移の取得
    useEffect(() => {
      const fetchData = async () => {
        if (!mangaDetail) return;

        try {
          const res = await fetch(
            `http://localhost:8080/ranking?work_id=${mangaDetail.work_id}`
          );

          if (!res.ok) {
            throw new Error("Failed to fetch volumes");
          }

          const dataRanking: RankingRow[] = await res.json();
          console.log(dataRanking)
          setEachWork(dataRanking);
        } catch (err) {
          console.error(err);
        }
      };

      fetchData();
    }, [mangaDetail]);


  useEffect(() => {
    const fetchVolumeData = async () => {
      if (!mangaDetail) return;

      try {
        const res = await fetch(
          `http://localhost:8080/volumes?work_id=${mangaDetail.work_id}`
        );

        if (!res.ok) {
          throw new Error("Failed to fetch volumes");
        }

        const data: Volume[] = await res.json();
        setVolumes(data);
      } catch (err) {
        console.error(err);
      }
    };

    fetchVolumeData();
  }, [mangaDetail]);

    if (loading) {
    return (
      <Container>
        <Typography>Loading...</Typography>
      </Container>
    );
  }

  if (!mangaDetail) {
    return (
      <Container>
        <Typography color="error">漫画が見つかりませんでした。</Typography>
      </Container>
    );
  }


  return (
    /* 全体のコンテナ：背景色を強制的に指定 */
    <div style={{
      backgroundColor: '#1b2230',
      color: '#ffffff',
      minHeight: '100vh',
      width: '100%',
      maxWidth: '400px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'sans-serif'
    }}>

      {/* ヘッダー */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '24px' }}>
        <Link to="/jumprank"><ChevronLeft size={24} color="#94a3b8" /></Link>
        <h1 style={{ fontSize: '18px', fontWeight: 'bold', letterSpacing: '0.2em', margin: 0 }}>{mangaDetail.title}｜著:{mangaDetail.author}</h1>
        <div style={{ width: '24px' }} />
      </div>

      {/* 4つのカードセクション */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '8px', marginBottom: '32px' }}>
        <StatBox title="最新順位" value={eachWork.length > 0 ? eachWork[0].rank_num : "-"} unit="位" color="#2a5496" />
        <StatBox title="平均順位" value="2.4" unit="位" color="#2d5a50" icon={<Triangle size={8} fill="#4ade80" color="#4ade80" />} />
        <StatBox title="最高順位" value="1" unit="位" color="#252b39" border="1px solid #334155" icon={<ArrowUp size={12} fill="#ef4444" color="#ef4444" />} />
        <StatBox title="最低順位" value="6" unit="位" color="#252b39" border="1px solid #334155" icon={<ArrowDown size={12} fill="#ef4444" color="#ef4444" />} />
      </div>

      {/* グラフエリア */}
      <div style={{ marginBottom: '32px' }}>
        <h2 style={{ fontSize: '14px', borderBottom: '1px solid #334155', paddingBottom: '4px', marginBottom: '16px' }}>順位推移</h2>
        <div style={{ height: '200px', width: '100%' }}>
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={data} margin={{ top: 10, right: 10, left: -40, bottom: 0 }}>
              <defs>
                <linearGradient id="gradBlue" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#60a5fa" stopOpacity={0.4}/>
                  <stop offset="100%" stopColor="#60a5fa" stopOpacity={0}/>
                </linearGradient>
                <linearGradient id="gradOrange" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#f87171" stopOpacity={0.4}/>
                  <stop offset="100%" stopColor="#f87171" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <CartesianGrid vertical={false} stroke="#334155" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10}} interval={1} />
              <YAxis reversed domain={[1, 3]} hide />

              <Area type="monotone" dataKey="orange" stroke="#f87171" fill="url(#gradOrange)" strokeWidth={2} dot={{ r: 4, fill: '#fff', stroke: '#f87171' }} />
              <Area type="monotone" dataKey="blue" stroke="#60a5fa" fill="url(#gradBlue)" strokeWidth={2} dot={{ r: 4, fill: '#fff', stroke: '#60a5fa' }} />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div style={{ marginBottom: '32px' }}>
      <h2 style={{ fontSize: '14px', borderBottom: '1px solid #334155', paddingBottom: '4px', marginBottom: '16px' }}>順位推移</h2>
      <div style={{ height: '200px', width: '100%' }}>
        <ResponsiveContainer width="100%" height="100%">
          {/* data: [{RankingID:115, WorkID:4, IssueID:0, Rank:1, RankChange:0}, ...] 
              という形式を想定 
          */}
          <AreaChart data={eachWork} margin={{ top: 10, right: 10, left: -40, bottom: 0 }}>
            <defs>
              <linearGradient id="gradBlue" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#60a5fa" stopOpacity={0.4}/>
                <stop offset="100%" stopColor="#60a5fa" stopOpacity={0}/>
              </linearGradient>
            </defs>
            <CartesianGrid vertical={false} stroke="#334155" />

            {/* XAxis: 適切なラベル（号数など）がない場合は index を表示するか、データに項目を追加してください */}
            <XAxis 
              dataKey="ranking_id" 
              axisLine={false} 
              tickLine={false} 
              tick={{fill: '#94a3b8', fontSize: 10}} 
              interval="preserveStartEnd" 
            />

            {/* YAxis: Rankが1に近いほど上にくるように reversed を使用 */}
            <YAxis 
              reversed 
              dataKey="rank_num" 
              domain={[1, 'dataMax + 1']} 
              hide 
            />

            <Tooltip 
              // マウスを当てた時に表示されるボックスのスタイル
              contentStyle={{ 
                backgroundColor: '#1a2235', 
                border: '1px solid #334155', 
                borderRadius: '4px',
                fontSize: '12px',
                color: '#fff'
              }}
              // 項目のスタイル
              itemStyle={{ color: '#60a5fa', fontWeight: 'bold' }}
              // 表示名のカスタマイズ
              formatter={(value: number) => [`${value}位`, '順位']}
              // ラベル（X軸の値）の非表示（必要に応じて）
              labelStyle={{ display: 'none' }}
              // カーソル（マウス位置の垂直線）のスタイル
              cursor={{ stroke: '#334155', strokeWidth: 1 }}
            />

            <Area 
              type="monotone" 
              dataKey="rank_num" // ここを新しいフォーマットのキー「Rank」に変更
              stroke="#60a5fa" 
              fill="url(#gradBlue)" 
              strokeWidth={2} 
              dot={{ r: 4, fill: '#fff', stroke: '#60a5fa', strokeWidth: 2 }} 
              activeDot={{ r: 6 }}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </div>

      {/* 下部のリスト */}
      <div>
        <h2 style={{ fontSize: '14px', marginBottom: '12px' }}>号別順位</h2>
        <ListRow label="第10号" value="1" />
        <ListRow label="第9号" value="2" />
        <ListRow label="第8号" value="3" />
      </div>

      {/* 単行本情報セクション */}
      <section style={{ marginTop: '32px', marginBottom: '40px' }}>
        <h2 style={{ fontSize: '14px', borderBottom: '1px solid #334155', paddingBottom: '4px', marginBottom: '16px' }}>最新刊情報</h2>
    {volumes.map((volume) => (
        <div style={{ 
          backgroundColor: '#252b39', 
          borderRadius: '8px', 
          padding: '16px', 
          display: 'flex', 
          gap: '16px',
          border: '1px solid #334155'
        }}>
          {/* 表紙イメージのプレースホルダー */}
          <div style={{ 
            width: '80px', 
            height: '120px', 
            backgroundColor: '#1b2230', 
            borderRadius: '4px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '10px',
            color: '#4b5563',
            border: '1px border #334155'
          }}>
            IMAGE
          </div>


          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
            <h3 style={{ fontSize: '16px', fontWeight: 'bold', margin: '0 0 8px 0' }}>{mangaDetail.title} {volume.volume}巻</h3>
            <div style={{ fontSize: '12px', color: '#94a3b8', marginBottom: '4px' }}>発売日: {new Date(volume.releaseDate).toLocaleDateString('ja-JP')}</div>
            <div style={{ fontSize: '12px', color: '#94a3b8', marginBottom: '12px' }}>価格: {volume.price.toLocaleString()}円 (税込)</div>

            <a 
            href={`https://www.shueisha.co.jp/books/items/contents.html?isbn=${volume.isbn}`}
            target="_blank" 
            rel="noopener noreferrer" 
            style={{ 
              display: 'block', // 幅いっぱいに広げる
              textAlign: 'center',
              textDecoration: 'none', // 下線を消す
              backgroundColor: '#2a5496', 
              color: 'white', 
              borderRadius: '4px', 
              padding: '10px 12px', 
              fontSize: '12px', 
              fontWeight: 'bold',
              transition: 'opacity 0.2s',
            }}
            onMouseOver={(e) => (e.currentTarget.style.opacity = '0.8')}
            onMouseOut={(e) => (e.currentTarget.style.opacity = '1')}
          >
            詳細を見る
          </a>
          </div>
        </div>
))}

        {/* 既刊リスト（簡易版） 
        <div style={{ marginTop: '16px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px', color: '#94a3b8', padding: '8px 4px' }}>
            <span>既刊合計</span>
            <span style={{ color: 'white', fontWeight: 'bold' }}>108巻</span>
          </div>
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px', color: '#94a3b8', padding: '8px 4px' }}>
            <span>累計発行部数</span>
            <span style={{ color: 'white', fontWeight: 'bold' }}>5億1,000万部以上</span>
          </div>
        </div>
        */}
      </section>

    </div>


  );
};

// --- スタイル付きサブコンポーネント ---

const StatBox = ({ title, value, unit, color, border, icon }: any) => (
  <div style={{
    backgroundColor: color,
    border: border || 'none',
    borderRadius: '4px',
    padding: '8px',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'space-between',
    alignItems: 'center',
    aspectRatio: '1/1'
  }}>
    <div style={{ fontSize: '9px', opacity: 0.8, textAlign: 'center' }}>{title}</div>
    <div style={{ display: 'flex', alignItems: 'baseline', gap: '2px' }}>
      <span style={{ fontSize: '20px', fontWeight: 'bold', fontStyle: 'italic' }}>{value}</span>
      <span style={{ fontSize: '10px' }}>{unit}</span>
      {icon && <span style={{ marginLeft: '2px' }}>{icon}</span>}
    </div>
  </div>
);

